    Help,
    Top,
    Json,
}

impl Action {
    /// 이 옵션이 받는 값의 수 (help·json 은 0, top 은 1)
    fn nargs(self) -> usize {
        match self {
            Action::Top => 1,
            Action::Help | Action::Json => 0,
        }
    }
}

/// argparse 에 등록된 순서대로
const OPTIONS: [(&str, Action); 4] = [
    ("-h", Action::Help),
    ("--help", Action::Help),
    ("--top", Action::Top),
    ("--json", Action::Json),
];

fn lookup(option: &str) -> Option<Action> {
    OPTIONS
        .iter()
        .find(|(name, _)| *name == option)
        .map(|&(_, action)| action)
}

